/// <summary>
/// DP class for SO MultimodalDangerousGoods
/// </summary>
[SrsReportParameterAttribute(classStr(METCommonReportContract))]
public class METSalesMultimodalDangerousGoodsDP extends SrsReportDataProviderPreProcessTempDB
{
    METSalesMultimodalDangerousGoodsTmp metSalesMultimodalDangerousGoodsTmp;
    METSalesMultimodalDangerousGoodsLineTmp metSalesMultimodalDangerousGoodsLineTmp;
    RecordInsertList    headerList, lineList;
    METBundleGuid         bundleHeaderReportGuid;
    METBundleGuid         headerReportGuid;

}

Method.Source:
/// <summary>
/// Set the bundling guid values to the tmp tables
/// </summary>
/// <param name = "_bundleHeaderReportGuid">Bundle header report guid</param>
/// <param name = "_headerReportGuid">Header report guid</param>
public void setBundlingGuid(METBundleGuid     _bundleHeaderReportGuid, METBundleGuid    _headerReportGuid)
{
    bundleHeaderReportGuid = _bundleHeaderReportGuid;
    headerReportGuid = _headerReportGuid;
}

/// <summary>
/// Get data from METSalesMultimodalDangerousGoodsTmp
/// </summary>
/// <returns>METSalesMultimodalDangerousGoodsTmp</returns>
[SrsReportDataSetAttribute(tableStr(METSalesMultimodalDangerousGoodsTmp))]
public METSalesMultimodalDangerousGoodsTmp getMETSalesMultimodalDangerousGoodsTmp()
{
    select metSalesMultimodalDangerousGoodsTmp;
    return metSalesMultimodalDangerousGoodsTmp;
}

/// <summary>
/// Get data from  METSalesMultimodalDangerousGoodsLineTmp
/// </summary>
/// <returns>METSalesMultimodalDangerousGoodsLineTmp</returns>
[SrsReportDataSetAttribute(tableStr(METSalesMultimodalDangerousGoodsLineTmp))]
public METSalesMultimodalDangerousGoodsLineTmp getMETSalesMultimodalDangerousGoodsLineTmp()
{
    select metSalesMultimodalDangerousGoodsLineTmp;
    return metSalesMultimodalDangerousGoodsLineTmp;
}

/// <summary>
/// Report business logic
/// </summary>
public void processReport()
{
    METSalesOrderShipmentLoadHeader     metSalesOrderShipmentLoadHeader;
    METSalesOrderShipmentLoadLines      metSalesOrderShipmentLoadLines;
    METCommonReportContract             contract = this.parmDataContract();
    const str export = "Export";
    SalesTable salesTable;
    METCustTable metCustTable;
    InventTable inventTable;

    headerList = new RecordInsertList(tableNum(METSalesMultimodalDangerousGoodsTmp), true, true, true, true, true, metSalesMultimodalDangerousGoodsTmp);
    lineList = new RecordInsertList(tableNum(METSalesMultimodalDangerousGoodsLineTmp), true, true, true, true, true, metSalesMultimodalDangerousGoodsLineTmp);

    select firstonly metSalesOrderShipmentLoadHeader
        where metSalesOrderShipmentLoadHeader.RecId == contract.parmRecId();

    metCustTable = MetCustTable::find(metSalesOrderShipmentLoadHeader.CustAccount);

    if (metCustTable.CustomerType != export)
    {
        return;
    }

    if (metSalesOrderShipmentLoadHeader.RecId && metCustTable.CustomerType == export)
    {
        this.insertHeaderData(metSalesOrderShipmentLoadHeader);

        headerList.insertDatabase();
    }

    while select ItemId, Quantity, RecId from metSalesOrderShipmentLoadLines
            where metSalesOrderShipmentLoadLines.ShipmentId == metSalesOrderShipmentLoadHeader.ShipmentId
        exists join inventTable
            where inventTable.ItemId == metSalesOrderShipmentLoadLines.ItemId
                && inventTable.HMIMIndicator == NoYes::Yes
    {
        this.insertLineData(metSalesOrderShipmentLoadLines);
    }
    lineList.insertDatabase();
}

/// <summary>
/// Insert into line table
/// </summary>
/// <param name = "_metSalesOrderShipmentLoadLines">METSalesOrderShipmentLoadLines</param>
public void insertLineData(METSalesOrderShipmentLoadLines _metSalesOrderShipmentLoadLines)
{
    InventTable inventTable;
    HMIMItemMaterial hmimItemMaterial;
    SalesLine salesLine;
    InventItemSalesSetup inventItemSalesSetup;
    InventDim inventDim;
    const str x = "X";

    metSalesMultimodalDangerousGoodsLineTmp.Qty = _metSalesOrderShipmentLoadLines.Quantity;

    select firstonly NetWeight, TaraWeight, UnitVolume from inventTable
        where inventTable.ItemId == _metSalesOrderShipmentLoadLines.ItemId;

    metSalesMultimodalDangerousGoodsLineTmp.GrossMass = (inventTable.NetWeight + inventTable.TaraWeight) * _metSalesOrderShipmentLoadLines.Quantity;
    metSalesMultimodalDangerousGoodsLineTmp.NetMass = inventTable.NetWeight * _metSalesOrderShipmentLoadLines.Quantity;
    metSalesMultimodalDangerousGoodsLineTmp.Cube = inventTable.UnitVolume * _metSalesOrderShipmentLoadLines.Quantity;
    metSalesMultimodalDangerousGoodsLineTmp.ShipmentLoadLinesRecId = _metSalesOrderShipmentLoadLines.RecId;

    select firstonly UnitOfMeasure, TechnicalNameCode, DivisionCode, PackingGroupCode, Flashpoint, EMSCode, Qty
        from hmimItemMaterial
        where hmimItemMaterial.ItemId == _metSalesOrderShipmentLoadLines.ItemId;

    metSalesMultimodalDangerousGoodsLineTmp.UN = hmimItemMaterial.UnitOfMeasure;
    metSalesMultimodalDangerousGoodsLineTmp.TechnicalNameCode = hmimItemMaterial.TechnicalNameCode;
    metSalesMultimodalDangerousGoodsLineTmp.DivisionCode = hmimItemMaterial.DivisionCode;
    metSalesMultimodalDangerousGoodsLineTmp.PackingGroupCode = hmimItemMaterial.PackingGroupCode;
    metSalesMultimodalDangerousGoodsLineTmp.Flashpoint = hmimItemMaterial.Flashpoint;
    metSalesMultimodalDangerousGoodsLineTmp.EMSCode = hmimItemMaterial.EMSCode;

    select firstonly SalesUnit, InventDimId from salesLine
        where salesLine.SalesId == _metSalesOrderShipmentLoadLines.OrderNum
        && salesLine.LineNum == _metSalesOrderShipmentLoadLines.LineNum;

    metSalesMultimodalDangerousGoodsLineTmp.KindOfPackage = salesLine.SalesUnit;

    select firstonly METSalesUnit from inventItemSalesSetup
        exists join inventDim
        where inventItemSalesSetup.InventDimId == inventDim.inventDimId
        && inventItemSalesSetup.ItemId == _metSalesOrderShipmentLoadLines.ItemId
        && inventDim.InventSiteId == InventDim::find(salesLine.InventDimId).InventSiteId;

    metSalesMultimodalDangerousGoodsLineTmp.InnerPackaging = any2Str(hmimItemMaterial.Qty)+ x + hmimItemMaterial.UnitOfMeasure;
    metSalesMultimodalDangerousGoodsLineTmp.OuterPackaging = any2Str(metSalesMultimodalDangerousGoodsLineTmp.NetMass) + " " +inventItemSalesSetup.METSalesUnit;

    metSalesMultimodalDangerousGoodsLineTmp.BundleReportHeaderGuidStr = bundleHeaderReportGuid;
    metSalesMultimodalDangerousGoodsLineTmp.MultimodalDangerousHeaderGuidStr = headerReportGuid;
    lineList.add(metSalesMultimodalDangerousGoodsLineTmp);
}

/// <summary>
/// Insert into header table
/// </summary>
/// <param name = "_metSalesOrderShipmentLoadHeader">METSalesOrderShipmentLoadHeader</param>
public void insertHeaderData(METSalesOrderShipmentLoadHeader _metSalesOrderShipmentLoadHeader)
{
    InventLocation inventLocationTo;
    METInventLocation metInventLocationTo;
    HMIMMultimodalDG hmimMultimodalDG;

    select firstonly inventLocationTo 
        where inventLocationTo.InventLocationId == _metSalesOrderShipmentLoadHeader.ToWarehouse;


    metSalesMultimodalDangerousGoodsTmp.WHName = inventLocationTo.Name;
    metSalesMultimodalDangerousGoodsTmp.WHAddress = inventLocationTo.address();

    select firstonly hmimMultimodalDG
        where hmimMultimodalDG.ShipmentId == _metSalesOrderShipmentLoadHeader.ShipmentId;

    metSalesMultimodalDangerousGoodsTmp.TransportDocumentNumber = hmimMultimodalDG.MMDGDocumentId;
    metSalesMultimodalDangerousGoodsTmp.ShipperPreparation = hmimMultimodalDG.ShipperPreparation;

    metSalesMultimodalDangerousGoodsTmp.ShipmentId = _metSalesOrderShipmentLoadHeader.ShipmentId;

    select firstonly metInventLocationTo
        where metInventLocationTo.InventLocation == inventLocationTo.RecId;

    metSalesMultimodalDangerousGoodsTmp.ConsigneeName = LogisticsLocation::find(CustTable::find(metInventLocationTo.InternalCustomer).postalAddress().Location).Description;
    metSalesMultimodalDangerousGoodsTmp.ConsigneeAddress = CustTable::find(metInventLocationTo.InternalCustomer).postalAddress().Address;

    metSalesMultimodalDangerousGoodsTmp.FreightForwarderReference = hmimMultimodalDG.FreightForwarderReference;
    metSalesMultimodalDangerousGoodsTmp.CarrierCode = hmimMultimodalDG.CarrierCode;
    metSalesMultimodalDangerousGoodsTmp.LoadingPort = hmimMultimodalDG.LoadingPort;
    metSalesMultimodalDangerousGoodsTmp.DischargePort = hmimMultimodalDG.DischargePort;
    metSalesMultimodalDangerousGoodsTmp.Destination = hmimMultimodalDG.Destination;

    metSalesMultimodalDangerousGoodsTmp.ShipmentLoadHeaderRecId = _metSalesOrderShipmentLoadHeader.RecId;
    metSalesMultimodalDangerousGoodsTmp.ContainerIdentificationNumber = hmimMultimodalDG.ContainerIdentificationNumber;
    metSalesMultimodalDangerousGoodsTmp.NoAndKindOfPackage = hmimMultimodalDG.SealNum;
    metSalesMultimodalDangerousGoodsTmp.TareMass = hmimMultimodalDG.ContainerTareWeight;
    metSalesMultimodalDangerousGoodsTmp.BundleReportHeaderGuidStr = bundleHeaderReportGuid;
    metSalesMultimodalDangerousGoodsTmp.MultimodalDangerousHeaderGuidStr = headerReportGuid;

    headerList.add(metSalesMultimodalDangerousGoodsTmp);
}
